package org.brightstats.desktop;

import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.stage.Window;
import org.brightstats.stats.FiniteMixture;

final class MixtureDialog {
    record Settings(FiniteMixture.Options mixture,boolean originalUnits){Settings{Objects.requireNonNull(mixture);}}
    private final Dialog<Settings> dialog=new Dialog<>();private final TextField segments=new TextField(),repetitions=new TextField(),iterations=new TextField(),tolerance=new TextField(),seed=new TextField(),floor=new TextField(),minimum=new TextField();private final CheckBox raw=new CheckBox("Use unstandardized normalized-weight composite scores"),intercept=new CheckBox("Estimate segment-specific regression intercepts");private final ComboBox<FiniteMixture.Initialization> initialization=new ComboBox<>();private final ComboBox<FiniteMixture.Stopping> stopping=new ComboBox<>();private Settings result;
    MixtureDialog(Window owner,Settings previous,int rows){var options=previous==null?FiniteMixture.Options.defaults():previous.mixture();dialog.initOwner(owner);dialog.setTitle("Finite mixture PLS segmentation");segments.setText(Integer.toString(options.segments()));repetitions.setText(Integer.toString(options.repetitions()));iterations.setText(Integer.toString(options.maxIterations()));tolerance.setText(Double.toString(options.tolerance()));seed.setText(Long.toString(options.seed()));floor.setText(Double.toString(options.varianceFloor()));minimum.setText(Double.toString(options.minimumMass()));raw.setSelected(previous!=null&&previous.originalUnits());intercept.setSelected(options.intercept());raw.selectedProperty().addListener((property,old,value)->{if(value)intercept.setSelected(true);});initialization.getItems().setAll(FiniteMixture.Initialization.values());initialization.setValue(options.initialization());stopping.getItems().setAll(FiniteMixture.Stopping.values());stopping.setValue(options.stopping());Label explanation=UiAppearance.label("The pooled PLS model supplies fixed score observations. Multiple starts seek different local optima; the highest-likelihood converged start is preferred. Class labels are arbitrary and sorted by mixture proportion. Review variance floors, weak classes and posterior uncertainty. Information criteria do not provide a regular likelihood-ratio test for the number of segments.");explanation.setWrapText(true);Label error=new Label();error.setWrapText(true);VBox content=new VBox(8,explanation,UiAppearance.label("Number of segments"),segments,UiAppearance.label("Independent starts"),repetitions,UiAppearance.label("Maximum iterations per start"),iterations,UiAppearance.label("Absolute stopping tolerance"),tolerance,UiAppearance.label("Base seed"),seed,UiAppearance.label("Residual variance floor (score units squared)"),floor,UiAppearance.label("Minimum fitted membership mass per class"),minimum,raw,intercept,UiAppearance.label("Initial partition"),initialization,UiAppearance.label("Convergence statistic"),stopping,error);content.setPadding(new Insets(12));ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefSize(690,680);dialog.getDialogPane().setContent(scroll);dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{var selected=new FiniteMixture.Options(Integer.parseInt(segments.getText().trim()),Integer.parseInt(repetitions.getText().trim()),Integer.parseInt(iterations.getText().trim()),Double.parseDouble(tolerance.getText().trim()),Long.parseLong(seed.getText().trim()),intercept.isSelected(),Double.parseDouble(floor.getText().trim()),Double.parseDouble(minimum.getText().trim()),initialization.getValue(),stopping.getValue());if(rows<selected.segments()*selected.minimumMass())throw new IllegalArgumentException("The requested class masses exceed available observations.");result=new Settings(selected,raw.isSelected());}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);}
    static Optional<Settings> show(Window owner,Settings previous,int rows){return new MixtureDialog(owner,previous,rows).dialog.showAndWait();}
    static Settings smokeTest(Window owner,int rows){var test=new MixtureDialog(owner,null,rows);test.dialog.show();test.segments.setText("0");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Zero mixture segments accepted");test.segments.setText("2");test.repetitions.setText("0");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Zero mixture starts accepted");test.repetitions.setText("3");test.iterations.setText("1000");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("Mixture settings lost");return test.dialog.getResult();}
}
